import type { Teacher } from './teacher-model';

export const QuizQuestionDifficultylevelKeyToLabel = {
  'DifficultylevelKey0': 'Easy',
  'DifficultylevelKey1': 'Medium',
  'DifficultylevelKey2': 'Hard'
} as const;
export type QuizQuestionDifficultylevelKey = keyof typeof QuizQuestionDifficultylevelKeyToLabel;

export interface QuizQuestion {
  /**
   * @displayName Quiz Question
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Quiz Question Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  quizquestionname: string;
  /**
   * @displayName Difficulty Level
   */
  difficultylevelKey?: QuizQuestionDifficultylevelKey;
  /**
   * @displayName Question Text
   * @validationRule Required for create/update operations
   */
  questiontext: string;
  /**
   * @displayName Subject
   */
  subject?: string;
  /**
   * @displayName Teacher Name
   */
  teachername?: Pick<Teacher, 'id' | 'fullname'>;
  /**
   * @displayName Topic
   */
  topic?: string;
}

export const _QuizQuestion = 'QuizQuestion' as const;